CREATE TABLE IF NOT EXISTS cms_apps(id INTEGER PRIMARY KEY AUTOINCREMENT,site_id INTEGER NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,app_key TEXT NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','archived')),navigation_json TEXT NOT NULL DEFAULT '[]',settings_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(site_id,app_key));
CREATE TABLE IF NOT EXISTS cms_app_entities(id INTEGER PRIMARY KEY AUTOINCREMENT,app_id INTEGER NOT NULL REFERENCES cms_apps(id) ON DELETE CASCADE,entity_key TEXT NOT NULL,label TEXT NOT NULL,plural_label TEXT NOT NULL,storage_type TEXT NOT NULL DEFAULT 'content' CHECK(storage_type IN('content','custom')),content_type_key TEXT,form_key TEXT,workflow_key TEXT,permissions_json TEXT NOT NULL DEFAULT '{}',settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(app_id,entity_key));
CREATE TABLE IF NOT EXISTS cms_app_relations(id INTEGER PRIMARY KEY AUTOINCREMENT,app_id INTEGER NOT NULL REFERENCES cms_apps(id) ON DELETE CASCADE,relation_key TEXT NOT NULL,source_entity_key TEXT NOT NULL,target_entity_key TEXT NOT NULL,relation_type TEXT NOT NULL CHECK(relation_type IN('one_to_one','one_to_many','many_to_many')),settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(app_id,relation_key));
CREATE TABLE IF NOT EXISTS cms_app_views(id INTEGER PRIMARY KEY AUTOINCREMENT,app_id INTEGER NOT NULL REFERENCES cms_apps(id) ON DELETE CASCADE,view_key TEXT NOT NULL,entity_key TEXT NOT NULL,view_type TEXT NOT NULL CHECK(view_type IN('list','detail','form','dashboard')),columns_json TEXT NOT NULL DEFAULT '[]',filters_json TEXT NOT NULL DEFAULT '[]',sort_json TEXT NOT NULL DEFAULT '[]',settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(app_id,view_key));
CREATE TABLE IF NOT EXISTS cms_app_routes(id INTEGER PRIMARY KEY AUTOINCREMENT,app_id INTEGER NOT NULL REFERENCES cms_apps(id) ON DELETE CASCADE,route_key TEXT NOT NULL,path TEXT NOT NULL,view_key TEXT NOT NULL,permission_key TEXT NOT NULL DEFAULT '',UNIQUE(app_id,route_key),UNIQUE(app_id,path));
CREATE TABLE IF NOT EXISTS cms_app_blueprints(id INTEGER PRIMARY KEY AUTOINCREMENT,blueprint_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,definition_json TEXT NOT NULL,version TEXT NOT NULL DEFAULT '1.0.0',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('10.25.0');